struct StoragePin { StorageWord slot{}, value{}; };
struct AccountPin { std::string_view name; EthAddress address{}; uint256 code_hash{}; std::vector<StoragePin> storage; };
template <size_t N> inline std::array<unsigned char,N> Fixed(std::string_view hex) {
    if (hex.size()!=N*2) throw std::runtime_error("compiled pin length");
    std::array<unsigned char,N> out{};
    const auto nibble=[](char c)->unsigned { if(c>='0'&&c<='9')return c-'0'; if(c>='a'&&c<='f')return c-'a'+10; throw std::runtime_error("compiled pin hex"); };
    for(size_t i=0;i<N;++i)out[i]=(nibble(hex[i*2])<<4)|nibble(hex[i*2+1]);
    return out;
}
inline uint256 Hash(std::string_view hex) { const auto value{Fixed<32>(hex)}; return uint256{std::span<const unsigned char>{value}}; }
