inline uint256 Digest() {
    static const uint256 digest=[] {
        proof_detail::Writer writer;
        writer.U64(11'155'111); writer.U64(421'614); writer.U64(DEPLOYMENT_BLOCK);
        writer.U64(LATEST_CONFIRMED_SLOT); writer.U64(ASSERTIONS_SLOT);
        writer.U32(Registry().size());
        for(const auto& pin:Registry()) {
            writer.Bytes(pin.address); writer.Root(pin.code_hash); writer.U32(pin.storage.size());
            for(const auto& slot:pin.storage) { writer.Bytes(slot.slot); writer.Bytes(slot.value); }
        }
        return peer::TaggedDigest("B3/arbitrum-sepolia-contract-settlement/1",writer.Take());
    }();
    return digest;
}
